                              FROM   (
                                      SELECT A.MASTER_ID, A.PLAN_ID, A.OUT_VERSION_ID, 
                                             A.LOT_ID, C.WORK_ORDER_ID, C.ITEM_ID, C.SITE_ID, C.ROUTE_ID, C.OPERATION_ID
                                      FROM   (
                                              SELECT MASTER_ID, PLAN_ID, OUT_VERSION_ID, ORDER_ID, LOT_ID
                                              FROM   TH_BUF_OUT_ORDER_TRACKING A
                                              WHERE  A.MASTER_ID      = @v_master_id
                                              AND    A.PLAN_ID        = @v_plan_id
                                              AND    A.OUT_VERSION_ID = @v_out_version_id
                                              AND    A.LOT_ID         IS NOT NULL
                                              AND    A.ORDER_ID_TYPE  = 'W'
                                              GROUP  BY MASTER_ID, PLAN_ID, OUT_VERSION_ID, ORDER_ID, LOT_ID
                                             ) A,
                                             TH_BUF_OUT_WORK_ORDER C
                                      WHERE  C.MASTER_ID      = @v_master_id
                                      AND    C.PLAN_ID        = @v_plan_id
                                      AND    C.OUT_VERSION_ID = @v_out_version_id
                                      AND    C.WORK_ORDER_ID  = A.ORDER_ID
                                     ) A,
                                     TH_MST_STOCK_PLAN B
                              WHERE  B.MASTER_ID      = @v_master_id
                              AND    B.PLAN_ID        = @v_plan_id
                              AND    A.LOT_ID         = B.LOT_ID
                             ) A
                             LEFT OUTER JOIN (
                                              SELECT ORDER_ID,
                                                     CASE WHEN R = 1 THEN ORDER_ID
                                                                     ELSE SUB_ORDER_ID
                                                     END  LANE_ORDER_ID
                                              FROM   TH_EXP_LANEORDER A,
                                                     (SELECT 1 R UNION ALL
                                                      SELECT 2 R ) B
                                              WHERE  A.MASTER_ID    = @v_master_id
                                              AND    A.PLAN_ID      = @v_plan_id
                                              AND    A.SUB_ORDER_ID IS NOT NULL
                                             ) B
                                  ON  A.TO_WORK_ORDER_ID = B.ORDER_ID
                     ) A
                     INNER JOIN TH_BUF_ORDER_PEGGING_MAP E
                           ON     1=1
                           AND    A.MASTER_ID           = E.MASTER_ID
                           AND    A.PLAN_ID             = E.PLAN_ID
                           AND    A.TO_WORK_ORDER_ID    = E.WORK_ORDER_ID
              WHERE (CASE WHEN A.LANE_ORDER_ID IS NULL THEN A.TO_QTY
                          ELSE E.COMPLETE_QTY
                     END  ) > 0 
             ) A
      GROUP  BY
             A.MASTER_ID, 
             A.PLAN_ID,
             A.COMPANY_ID,
             A.DIVISION_ID,
             A.SITE_ID,
             A.PLANT_ID,
             A.FROM_WORK_ORDER_ID,
             A.FROM_STOCK_SET_ID,
             A.TO_WORK_ORDER_ID,
             A.FROM_FACTORY_ID,
             A.TO_FACTORY_ID,
             A.FROM_LINE_ID,
             A.TO_LINE_ID,
             A.FROM_OPERATION_ID,
             A.TO_OPERATION_ID,
             A.FROM_ITEM_ID,
             A.TO_ITEM_ID
            
      --LOG 생성
      SET @v_message = @@ROWCOUNT
      SET @n_log_count += 1
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'TH_EXP_ORDER_PEGGING', 'INSERT', @n_log_count, null, @v_message, null 


      DELETE FROM SY_FP_ORDER_PEGGING_R
      WHERE  INSTANCE_ID = @v_master_id
      AND    FP_PLAN_ID = @v_plan_id

      INSERT INTO SY_FP_ORDER_PEGGING_R
            (
               INSTANCE_ID
             , FP_PLAN_ID
             , COMPANY_ID
             , DIVISION_ID
             , SITE_ID
             , PLANT_ID
             , FROM_WORK_ORDER_ID
             , FROM_STOCK_SET_ID
             , TO_WORK_ORDER_ID
             , FROM_FACTORY_ID
             , TO_FACTORY_ID
             , FROM_LINE_ID
             , TO_LINE_ID
             , FROM_OPERATION_ID
             , TO_OPERATION_ID
             , FROM_QTY
             , TO_QTY
             , FROM_ITEM_ID
             , TO_ITEM_ID
             , DEMAND_ID
             , INSERT_ID
             , INSERT_TIME
            )      
      SELECT 
             A.INSTANCE_ID
           , A.FP_PLAN_ID
           , A.COMPANY_ID
           , A.DIVISION_ID
           , A.SITE_ID
           , A.PLANT_ID
           , A.FROM_WORK_ORDER_ID
           , A.FROM_STOCK_SET_ID
           , A.TO_WORK_ORDER_ID
           , A.FROM_FACTORY_ID
           , A.TO_FACTORY_ID
           , A.FROM_LINE_ID
           , A.TO_LINE_ID
           , A.FROM_OPERATION_ID
           , A.TO_OPERATION_ID
           , A.FROM_QTY
           , SUM(A.TO_QTY) AS TO_QTY
           , A.FROM_ITEM_ID
           , A.TO_ITEM_ID
           , A.DEMAND_ID
           , A.INSERT_ID
           , A.INSERT_TIME
      FROM   TH_EXP_ORDER_PEGGING A
      WHERE  A.INSTANCE_ID  = @v_master_id
      AND    A.FP_PLAN_ID   = @v_plan_id
      GROUP  BY
             A.INSTANCE_ID
           , A.FP_PLAN_ID
           , A.COMPANY_ID
           , A.DIVISION_ID
           , A.SITE_ID
           , A.PLANT_ID
           , A.FROM_WORK_ORDER_ID
           , A.FROM_STOCK_SET_ID
           , A.TO_WORK_ORDER_ID
           , A.FROM_FACTORY_ID
           , A.TO_FACTORY_ID
           , A.FROM_LINE_ID
           , A.TO_LINE_ID
           , A.FROM_OPERATION_ID
           , A.TO_OPERATION_ID
           , A.FROM_QTY
           , A.FROM_ITEM_ID
           , A.TO_ITEM_ID
           , A.DEMAND_ID
           , A.INSERT_ID
           , A.INSERT_TIME
      
      --LOG 생성
      SET @v_message = @@ROWCOUNT
      SET @n_log_count += 1
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, 'SY_FP_ORDER_PEGGING_R', 'INSERT', @n_log_count, null, @v_message, null 
      
      --LOG 생성
      EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_proc_name, null, 'END', 999999, null, '=============== End of procedure ===============', null
      
    END TRY

    BEGIN CATCH
      BEGIN

        DECLARE 
          @v_error_message nvarchar(max),
          @v_error_procedure nvarchar(max),
          @v_error_line nvarchar(max)

        SET @v_error_message = ERROR_MESSAGE()

        SET @v_error_procedure = ERROR_PROCEDURE()

        SET @v_error_line = convert(nvarchar,ERROR_LINE())


        EXECUTE pr_log_process  null, @v_master_id, @v_plan_id, @v_error_procedure, null, 'ERROR', null, @v_error_line, null, @v_error_message

        IF @@TRANCOUNT > 0
          COMMIT WORK 
      END
    END CATCH
END
